# ---- v61 · ÖN KAPAKLAR ŞEFFAF (Kemal: "ön kapakları şeffaf yap, çekmeceleri de") — yalnız görünüm, parça ve denetim aynı
import re as _re61
MALZEME["on_seffaf"] = dict(renk=(0.70, 0.82, 0.95, 0.16), met=0.1, ruf=0.15, saydam=True)
ON_SEFFAF = _re61.compile(r"^(onyuz_|CEK_K\d_[a-z0-9]+_\d+_on_(dis_sac|pu|ic_sac|fitil)|k4_kapak_|k4_izgara_|serit_on_|klape_levhasi$|servis_kapagi_|"
                          r"musteri_(alt|ust)_panel$|goz_\d\d_musteri_kapisi$|on_kapak$|cekmece_onu$|on_ust_kapak$)")
# v91 · ÇERÇEVE SAYDAM DEĞİL (Kemal: TOPPING'de "bu ne havada uçuyor" = mekanizma bandının ön çerçevesi) — "onyuz_" adlı çerçeve / dikme / kayıt / kuşak / plint /
#       dayama dudağı / lama / menteşe tabanı / kılavuz / emniyet sensörü / ışık perdesi opak kalır; yalnız kapak kanadı, paneli ve kanada bağlı donanım saydam.
#       v91 · E şarjör yan kapısı listeden çıktı (Kemal: "kırmızı seçtiğim dış gövdeyle aynı olmalı" — saydam kapıdan içerideki kılavuz taşıyıcı şerit gibi görünüyordu)
ON_CERCEVE = _re61.compile(r"(cerceve(?!_saci)|dikme|kayit|kusak|plint|dayama|lama|mentese_tabani|kilavuz|emniyet_sensoru|isik_perdesi|mentese_\d+_sabit|mentese_sabit|mentese_\d+_taban|basac(?!_K\d)|panel_tutucu)")   # v92: gövdedeki menteşe yarısı, basmalı kilit, panel tutucusu da opak · TOPPING soğuk dolap K1/K2 kilidi saydam yüz sacına bağlı, kapakla saydam kalır   # yüz sacı (çerçeve SACI) saydam kalır: B çekmeceleri görünsün


def _seffaf_mi(ad):
    return bool(ON_SEFFAF.match(ad)) and not ON_CERCEVE.search(ad)



_ON61 = {}
for _ad61, _L61 in (("B", SC.PARCALAR), ("QR", QR.PARCALAR), ("TEZGAH", TZ.PARCALAR), ("E", KC.PARCALAR), ("K", KS.PARCALAR), ("A", AK.PARCALAR), ("D", FU.PARCALAR), ("BULASIK", BM.PARCALAR), ("TU", TU.P), ("U", UD.PARCALAR)):
    for _p61 in _L61:
        if _seffaf_mi(_p61["ad"]):
            _p61["mal"] = "on_seffaf"; _ON61[_ad61] = _ON61.get(_ad61, 0) + 1
print("v61 · ON KAPAKLAR SEFFAF (yalniz gorunum): " + " · ".join("%s %d parca" % kv for kv in sorted(_ON61.items())))
assert all(_ON61.get(k_, 0) > 0 for k_ in ("B", "QR", "TEZGAH", "E")), _ON61
