    for p in _TABLA:
        for _ad_, _xk in (("park", TC.XC_TABLA), ("aktarma", TH.X_AKTARMA)):
            _DGI.append(("TABLA(%s):%s" % (_ad_, p["ad"]), p["wp"].val().translate(cq.Vector(X_BC + _xk - TC.XC_TABLA, Y_MEK, 0.0))))
    for q in TU.P:
        if q["ad"].startswith(V3_CIKAN): continue
